using Microsoft.EntityFrameworkCore;
using seed_b_backend.Api.Data;
using seed_b_backend.Api.Data.Entities;
using seed_b_backend.Api.Dtos;

namespace seed_b_backend.Api.Services;

public class ProductQueryService(AppDbContext db)
{
    private const int PageSize = 20;

    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(int page, string? categoryId = null, string? subcategoryId = null)
    {
        page = page < 1 ? 1 : page;

        IQueryable<Product> query = db.Products.Include(p => p.Subcategory);

        if (!string.IsNullOrEmpty(subcategoryId))
        {
            query = query.Where(p => p.SubcategoryId == subcategoryId);
        }
        else if (!string.IsNullOrEmpty(categoryId))
        {
            query = query.Where(p => p.Subcategory!.CategoryId == categoryId);
        }

        var totalCount = await query.CountAsync();

        // long arithmetic + clamp to totalCount avoids an int overflow into a negative
        // Skip() for very large page values while preserving "beyond last page -> empty" behavior.
        var skip = (int)Math.Min((long)(page - 1) * PageSize, totalCount);

        var items = await query
            .OrderBy(p => p.Name)
            .ThenBy(p => p.Id)
            .Skip(skip)
            .Take(PageSize)
            .Select(p => new ProductListItemDto(
                p.Id,
                p.Name,
                p.Subcategory!.Name,
                p.Offers.Min(o => o.Price)))
            .ToListAsync();

        var totalPages = (int)Math.Ceiling(totalCount / (double)PageSize);

        return new PagedResultDto<ProductListItemDto>(items, page, PageSize, totalCount, totalPages);
    }
}

using Microsoft.EntityFrameworkCore;
using seed_b_backend.Api.Data.Entities;

namespace seed_b_backend.Api.Data;

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Category> Categories => Set<Category>();
    public DbSet<Subcategory> Subcategories => Set<Subcategory>();
    public DbSet<Supplier> Suppliers => Set<Supplier>();
    public DbSet<Product> Products => Set<Product>();
    public DbSet<Offer> Offers => Set<Offer>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Category>()
            .HasMany(c => c.Subcategories)
            .WithOne(s => s.Category)
            .HasForeignKey(s => s.CategoryId);

        modelBuilder.Entity<Subcategory>()
            .HasMany(s => s.Products)
            .WithOne(p => p.Subcategory)
            .HasForeignKey(p => p.SubcategoryId);

        modelBuilder.Entity<Product>()
            .Property(p => p.ViewCount)
            .HasDefaultValue(0);

        modelBuilder.Entity<Offer>(o =>
        {
            o.HasKey(x => new { x.ProductId, x.SupplierId });
            o.Property(x => x.Price).HasColumnType("decimal(18,2)");

            o.HasOne(x => x.Product)
                .WithMany(p => p.Offers)
                .HasForeignKey(x => x.ProductId);

            o.HasOne(x => x.Supplier)
                .WithMany(s => s.Offers)
                .HasForeignKey(x => x.SupplierId);
        });
    }
}

